import{_ as a,o as i,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2020-11-12","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-11-12","date":"2020-11-12T00:00:00.000Z","updated":"2020-11-25T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","CRUSH算法","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-11-12.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-11-12.md","lastUpdated":1780460162000}'),t={name:"posts/2020/Ceph_Performance_Meeting_2020-11-12.md"};function o(n,l,s,h,d,u){return i(),e("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="与会人员" tabindex="-1">与会人员 <a class="header-anchor" href="#与会人员" aria-label="Permalink to &quot;与会人员&quot;">​</a></h4><ul><li>Mark</li><li>Gary</li><li>Gabby</li><li>其他核心团队成员</li></ul><h4 id="缺席人员" tabindex="-1">缺席人员 <a class="header-anchor" href="#缺席人员" aria-label="Permalink to &quot;缺席人员&quot;">​</a></h4><ul><li>Adam（因波兰独立日休假）</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>性能分析进展</strong></p><ul><li>Gabby汇报了性能分析的进展，强调需要改进系统以记录和命名测试案例。</li><li>讨论了使用CBT创建数据库模式来存储和查询测试结果的想法，但尚未实施。</li></ul></li><li><p><strong>Ceph性能优化</strong></p><ul><li>讨论了Python压缩对性能的影响，特别是PG信息和PG日志分离到不同列族的影响。</li><li>提到使用Wall Clock Profiler或Welcome Profiler来更清晰地展示性能差异。</li><li>讨论了添加统计信息（如压缩和闪存事件）的显示方式，建议通过admin socket命令获取。</li></ul></li><li><p><strong>监控插件的开发</strong></p><ul><li>讨论了开发一个监控插件以执行任意admin socket命令的必要性，以更好地收集和分析数据。</li><li>提到在CBT中实现一个自定义监控类的可能性。</li></ul></li><li><p><strong>PR更新</strong></p><ul><li>讨论了Intel的librbd客户端缓存实现的PR，Jason将继续审查。</li><li>更新了关于RocksDB动态级别的PR，Adam将在假期后继续跟进。</li><li>讨论了Igor的PG移除优化PR，已由Adam和Neha审查，但需要处理一些细节。</li></ul></li><li><p><strong>内存管理</strong></p><ul><li>Adam和Mark正在研究减少碎片化的内存管理策略。</li></ul></li><li><p><strong>MClock调度器测试</strong></p><ul><li>Sridhar分享了关于MClock调度器的最新测试结果，展示了在不同配置下的性能数据。</li><li>讨论了在单个shard和16个线程配置下的性能问题，需要进一步调查。</li></ul></li><li><p><strong>资源分配</strong></p><ul><li>Mark提到为开发人员提供高性能机器的计划，Gabby和Ronan将成为首批使用者。</li></ul></li><li><p><strong>RGW文件访问接口</strong></p><ul><li>讨论了RGW的文件访问接口，以及与IO500基准测试的合作可能性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>开发一个监控插件以执行任意admin socket命令。</li><li>进一步调查单个shard和16个线程配置下的性能问题。</li><li>为开发人员提供高性能机器，以便进行更深入的性能测试。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Gabby将继续进行性能分析。</li><li>调查和优化MClock调度器的性能。</li><li>为开发人员提供高性能机器，并鼓励他们使用这些资源进行性能测试。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>讨论了KV-Sync线程的性能瓶颈问题，需要进一步调查。</li><li>需要进一步调查和优化RocksDB的性能，特别是PG信息和PG日志分离到不同列族的性能影响。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议讨论了Ceph性能优化的多个议题，包括性能分析、监控插件开发、PR更新、内存管理、MClock调度器测试等。团队将继续进行调查和优化，以提高Ceph的整体性能。</p>',15)])])}const _=a(t,[["render",o]]);export{p as __pageData,_ as default};
